import numpy as np

def dropout_forward(x: np.ndarray, drop_prob: float = 0.5, training: bool = True, seed: int = None):
    if not training or drop_prob == 0.0:
        return x, None
    if seed is not None:
        np.random.seed(seed)
    keep_prob = 1.0 - drop_prob
    mask = (np.random.rand(*x.shape) >= drop_prob) / keep_prob
    out = x * mask
    return out, mask

def dropout_backward(dout: np.ndarray, mask: np.ndarray):
    if mask is None:
        return dout
    return dout * mask

dropout_forward(np.ones((2, 2)), drop_prob=0.5, training=False)[0]
